from __future__ import annotations

import typing

import pytest

from llm_router._internal.providers.retry import (
    RetryPolicy,
    build_provider_async_retrying,
    is_retryable_provider_error,
)

pytestmark = pytest.mark.verification_kind("unit")


def _build_retryable_error() -> Exception:
    """Find or construct an exception instance recognized as retryable."""
    for obj in list(is_retryable_provider_error.__globals__.values()):
        if isinstance(obj, type) and issubclass(obj, BaseException) and obj not in (BaseException, Exception):
            try:
                class SpecificRetryableError(obj):
                    retryable = True
                    is_retryable = True
                    status_code = 429
                    code = 429

                err = SpecificRetryableError("provider temporary failure")
                if is_retryable_provider_error(err):
                    return err
            except Exception:
                pass

            for args in [("provider temporary failure",), ()]:
                for kwargs in [{"retryable": True}, {"is_retryable": True}, {"status_code": 429}, {}]:
                    try:
                        err = obj(*args, **kwargs)
                        setattr(err, "retryable", True)
                        setattr(err, "is_retryable", True)
                        setattr(err, "status_code", 429)
                        if is_retryable_provider_error(err):
                            return err
                    except Exception:
                        pass

    class GenericRetryableError(Exception):
        retryable = True
        is_retryable = True
        status_code = 429
        code = 429

    generic_err = GenericRetryableError("provider temporary failure")
    if is_retryable_provider_error(generic_err):
        return generic_err

    for base in [TimeoutError, ConnectionError, OSError, RuntimeError]:
        try:
            class BuiltinSubclassError(base):
                retryable = True
                is_retryable = True
                status_code = 429
                code = 429

            err = BuiltinSubclassError("provider temporary failure")
            if is_retryable_provider_error(err):
                return err
        except Exception:
            pass

    return generic_err


@pytest.mark.asyncio
@pytest.mark.verifies("TREQ_PROVIDER_RETRY_BOUNDS[revision==1]")
async def test_provider_async_retrying_reraises_provider_error_on_exhaustion() -> None:
    max_attempts = 3
    try:
        policy = RetryPolicy(
            min_wait_seconds=0.0,
            max_wait_seconds=0.0,
            max_attempts=max_attempts,
        )
    except Exception:
        policy = RetryPolicy(
            min_wait_seconds=0.001,
            max_wait_seconds=0.001,
            max_attempts=max_attempts,
        )

    retrying = build_provider_async_retrying(
        policy=policy,
        logger=None,
        context_getter=None,
        state_sink=None,
    )

    last_error = _build_retryable_error()
    assert is_retryable_provider_error(last_error) is True

    call_count = 0

    async def failing_provider() -> typing.NoReturn:
        nonlocal call_count
        call_count += 1
        raise last_error

    with pytest.raises(type(last_error)) as exc_info:
        await retrying(failing_provider)

    assert call_count == max_attempts
    assert exc_info.value is last_error
    assert type(exc_info.value).__name__ != "RetryError"
